 DROP TEMPORARY TABLE rrc084_entries;
 DROP TEMPORARY TABLE rrc084_recipes;
 DROP TEMPORARY TABLE rrc084_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC084' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
